example.query:
query accounts {
  uiapi {
    query {
      Account(first: 10) {
        edges {
          node {
            Id
            Name { value displayValue }
            Industry { value displayValue }
          }
        }
        totalCount
      }
    }
  }
}

query getAccount($id: ID!) {
  uiapi {
    query {
      Account(where: { Id: { eq: $id } }) {
        edges {
          node {
            Id
            Name { value }
          }
        }
      }
    }
  }
}
